const f = $input.first().json;
function s(v) { return v === undefined || v === null ? '' : String(v).trim(); }
function noBraces(t) { return t.split('{').join('(').split('}').join(')'); }
const errors = [];
const warnings = [];
const missing = [];

const categoryLabel = s(f['Waste category']);
const CAT_MAP = { 'plastic': 'plastic', 'paper': 'paper', 'metal': 'metal', 'e-waste': 'e-waste', 'organic waste': 'organic waste', 'glass': 'glass', 'other': 'other' };
const category = CAT_MAP[categoryLabel.toLowerCase()] || '';
if (!category) errors.push('Waste category is missing or not recognised.');

const description = noBraces(s(f['Waste description']));
if (description.length < 10) errors.push('Please describe the waste in at least 10 characters (what it is and what it is made of).');

const condition = s(f['Condition']) || 'Unknown / not sure';
if (condition.indexOf('Unknown') === 0) missing.push('Condition of the material (clean, mixed or damaged)');

let qRaw = s(f['Quantity (kg)']).toLowerCase().split(',').join('').split('kg').join('').trim();
let mult = 1;
if (qRaw.endsWith('k')) { mult = 1000; qRaw = qRaw.slice(0, -1); }
const qty = parseFloat(qRaw) * mult;
const qtyOk = isFinite(qty) && qty > 0;
if (!qtyOk) errors.push('Quantity must be a number greater than 0 (in kg).');

const location = noBraces(s(f['Location']));
if (location.length < 2) errors.push('Location is required (city and state/region).');

let email = s(f['Contact email']);
if (email && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) {
  warnings.push('The email address looks invalid, so no email will be sent.');
  email = '';
}

let photo = s(f['Photo URL']);
if (photo && !/^https?:\/\//i.test(photo)) {
  warnings.push('Photo URL must start with http:// or https:// - it was ignored.');
  photo = '';
}
if (!photo) missing.push('Photo of the material (optional, can improve classification)');

const errorsHtml = errors.map(function (e) { return '<li>' + e.split('<').join('&lt;') + '</li>'; }).join('');

return [{ json: {
  is_valid: errors.length === 0,
  errors: errors,
  errors_html: errorsHtml,
  warnings: warnings,
  missing_info: missing,
  category: category,
  category_label: categoryLabel,
  description: description,
  condition: condition,
  quantity_kg: qtyOk ? Math.round(qty * 100) / 100 : null,
  location: location,
  email: email,
  photo_url: photo,
  submitted_at: s(f.submittedAt)
} }];

