const v = $('Validate Input').first().json;
const ai = $input.first().json || {};
const CATS = ['plastic', 'paper', 'metal', 'e-waste', 'organic waste', 'glass', 'other'];
const RULES = {
  'plastic': { subtype: 'Plastic - resin type not confirmed', keywords: ['plastic', 'pet', 'hdpe', 'ldpe', 'pp'], industries: ['Plastic recycling and regranulation', 'Recycled-content packaging', 'Construction products such as plastic lumber'], opportunities: [
    { product: 'Recycled plastic pellets', industry: 'Plastics processing', explanation: 'Clean plastic of a single resin type may be regranulated into pellets for new products, subject to processor acceptance.' },
    { product: 'Plastic lumber or outdoor furniture', industry: 'Construction and furniture', explanation: 'Some rigid plastics are used in composite boards, depending on processor requirements.' }],
    notes: 'Recyclability depends on resin type (check the recycling code), cleanliness and whether different plastics are mixed.' },
  'paper': { subtype: 'Paper or cardboard - grade not confirmed', keywords: ['paper', 'cardboard', 'newspaper', 'office paper'], industries: ['Paper mills', 'Recycled packaging and board', 'Moulded pulp products'], opportunities: [
    { product: 'Recycled cardboard and packaging board', industry: 'Packaging', explanation: 'Dry, clean paper and cardboard may be pulped into recycled board.' },
    { product: 'Moulded pulp trays or egg cartons', industry: 'Moulded fibre', explanation: 'Lower-grade paper fibre is sometimes used for moulded pulp items.' }],
    notes: 'Wet, greasy, waxed or plastic-laminated paper is often not accepted by paper recyclers.' },
  'metal': { subtype: 'Metal - alloy not confirmed', keywords: ['metal', 'aluminium', 'steel', 'iron', 'copper', 'tin'], industries: ['Scrap metal dealers', 'Smelters and foundries', 'Fabrication workshops'], opportunities: [
    { product: 'Secondary metal ingots', industry: 'Smelting', explanation: 'Separated ferrous and non-ferrous scrap may be remelted, subject to grade and purity.' },
    { product: 'Reused fabrication stock', industry: 'Workshops and makers', explanation: 'Usable offcuts or sheets may be reused directly in small fabrication.' }],
    notes: 'Value and acceptance depend on metal type, separation and contamination (paint, plastic, oil).' },
  'e-waste': { subtype: 'Electronic waste - device types not confirmed', keywords: ['e-waste', 'electronics', 'batteries', 'circuit boards', 'cables'], industries: ['Authorised e-waste recyclers', 'Refurbishment and repair', 'Precious-metal recovery'], opportunities: [
    { product: 'Refurbished devices or spare parts', industry: 'Repair and refurbishment', explanation: 'Working or repairable devices may have reuse potential before recycling.' },
    { product: 'Recovered metals from boards and cables', industry: 'Materials recovery', explanation: 'Authorised recyclers may recover copper and other metals from components.' }],
    notes: 'E-waste can contain hazardous parts (batteries, screens). Use authorised handlers only; batteries may need separate handling.' },
  'organic waste': { subtype: 'Organic waste - composition not confirmed', keywords: ['organic waste', 'food waste', 'garden waste', 'biomass'], industries: ['Composting', 'Biogas plants', 'Animal feed (only where regulations allow)'], opportunities: [
    { product: 'Compost or soil conditioner', industry: 'Agriculture and landscaping', explanation: 'Segregated organic waste may be composted if free of plastics and contaminants.' },
    { product: 'Biogas feedstock', industry: 'Renewable energy', explanation: 'Food and agricultural waste can potentially feed anaerobic digesters.' }],
    notes: 'Organic waste degrades quickly; contamination with plastics or chemicals often makes it unsuitable.' },
  'glass': { subtype: 'Glass - type and colour not confirmed', keywords: ['glass', 'bottles', 'jars', 'cullet'], industries: ['Glass manufacturing (cullet)', 'Construction aggregates', 'Decorative and craft reuse'], opportunities: [
    { product: 'Cullet for new glass containers', industry: 'Glass manufacturing', explanation: 'Container glass sorted by colour may be crushed into cullet, subject to acceptance.' },
    { product: 'Glass aggregate', industry: 'Construction', explanation: 'Crushed mixed glass is sometimes used as an aggregate substitute.' }],
    notes: 'Window glass, ceramics, mirrors and heat-resistant glass are usually not accepted with container glass.' },
  'other': { subtype: 'Unclassified material', keywords: ['other'], industries: ['Specialist recyclers (depends on the actual material)', 'Upcycling and reuse networks'], opportunities: [
    { product: 'Depends on the material', industry: 'To be determined', explanation: 'Add a more detailed description (what the item is made of) so a better match can be found.' }],
    notes: 'The material type is unclear, so recyclability cannot be assessed.' }
};
function arr(x) { return Array.isArray(x) ? x.filter(function (i) { return i !== null && i !== undefined && i !== ''; }) : []; }
function str(x, d) { return (typeof x === 'string' && x.trim()) ? x.trim() : d; }

let parsed = null;
let failReason = '';
if (ai.error) {
  failReason = 'AI service error: ' + (typeof ai.error === 'string' ? ai.error : (ai.error.message || 'unknown error'));
} else {
  const t = typeof ai.text === 'string' ? ai.text.trim() : '';
  const a = t.indexOf('{');
  const b = t.lastIndexOf('}');
  if (a >= 0 && b > a) {
    try { parsed = JSON.parse(t.slice(a, b + 1)); } catch (e) { failReason = 'AI returned text that was not valid JSON.'; }
  } else {
    failReason = 'AI returned no structured JSON output.';
  }
}

let c;
if (parsed && typeof parsed === 'object') {
  let mt = String(parsed.material_type || '').toLowerCase().trim();
  const notes = [];
  if (CATS.indexOf(mt) < 0) { notes.push('AI material type was not one of the supported categories; your selected category was used.'); mt = v.category; }
  let conf = String(parsed.confidence || 'low').toLowerCase();
  if (['low', 'medium', 'high'].indexOf(conf) < 0) conf = 'low';
  const opps = arr(parsed.value_opportunities).map(function (o) {
    return { product: str(o && o.product, 'Not specified'), industry: str(o && o.industry, 'Not specified'), explanation: str(o && o.explanation, '') };
  });
  c = {
    source: 'ai',
    source_label: 'AI classification (gpt-5-mini)' + (v.photo_url ? ' using description and photo' : ' using description only'),
    material_type: mt,
    subtype: str(parsed.subtype, 'unknown'),
    condition_assessment: str(parsed.condition_assessment, v.condition),
    confidence: conf,
    recyclability_notes: str(parsed.recyclability_notes, ''),
    certainty_caveat: str(parsed.certainty_caveat, ''),
    contamination_risks: arr(parsed.contamination_risks),
    reuse_industries: arr(parsed.reuse_industries),
    value_opportunities: opps.length ? opps : RULES[mt].opportunities,
    handling_precautions: arr(parsed.handling_precautions),
    missing_information: arr(parsed.missing_information).concat(notes),
    match_keywords: arr(parsed.match_keywords).map(function (k) { return String(k).toLowerCase().trim(); })
  };
} else {
  const r = RULES[v.category] || RULES['other'];
  c = {
    source: 'rule_based_fallback',
    source_label: 'RULE-BASED FALLBACK (AI classification unavailable) - based only on the category you selected',
    material_type: v.category,
    subtype: r.subtype,
    condition_assessment: 'As reported by you: ' + v.condition,
    confidence: 'low',
    recyclability_notes: r.notes,
    certainty_caveat: 'This is a generic rule-based estimate. The actual material composition has not been analysed.',
    contamination_risks: [],
    reuse_industries: r.industries,
    value_opportunities: r.opportunities,
    handling_precautions: [],
    missing_information: [],
    match_keywords: r.keywords
  };
}

const cond = v.condition.toLowerCase();
if (c.confidence !== 'high' || cond.indexOf('mixed') >= 0 || cond.indexOf('unknown') >= 0) {
  const extra = 'Recyclability is not certain: composition and condition must be confirmed by the receiving organisation.';
  c.certainty_caveat = c.certainty_caveat ? c.certainty_caveat + ' ' + extra : extra;
}
if (c.material_type !== v.category) {
  c.missing_information.push('AI classified this as ' + c.material_type + ' but you selected ' + v.category_label + '. Please double-check the category.');
}
c.missing_information = v.missing_info.concat(c.missing_information);

return [{ json: Object.assign({}, v, { classification: c, ai_failure_reason: failReason }) }];

const sub = $('Classification Fallback Handler').first().json;
const c = sub.classification;
const items = $input.all().map(function (i) { return i.json || {}; });
const dbError = items.find(function (r) { return r.error; });
const rows = items.filter(function (r) { return r.org_name; });
const qty = Number(sub.quantity_kg);

const primary = [c.material_type, sub.category].filter(function (t, i, a) { return t && t !== 'other' && a.indexOf(t) === i; });
const keywords = c.match_keywords.filter(function (k) { return k && primary.indexOf(k) < 0; });

const compatible = [];
const excluded = [];
rows.forEach(function (r) {
  const accepted = String(r.accepted_materials || '').toLowerCase().split(',').map(function (a) { return a.trim(); }).filter(Boolean);
  const primaryHits = primary.filter(function (t) { return accepted.indexOf(t) >= 0; });
  const keywordHits = keywords.filter(function (k) { return accepted.indexOf(k) >= 0; });
  if (!primaryHits.length && !keywordHits.length) {
    excluded.push({ org_name: r.org_name, reason: 'Does not accept ' + (c.material_type || sub.category) });
    return;
  }
  const minQ = Number(r.min_quantity_kg) || 0;
  const maxQ = Number(r.max_quantity_kg) || 0;
  if (qty < minQ) { excluded.push({ org_name: r.org_name, reason: 'Quantity ' + qty + ' kg is below its minimum of ' + minQ + ' kg' }); return; }
  if (maxQ > 0 && qty > maxQ) { excluded.push({ org_name: r.org_name, reason: 'Quantity ' + qty + ' kg is above its maximum of ' + maxQ + ' kg' }); return; }
  compatible.push(Object.assign({}, r, {
    material_match: primaryHits.length ? 'category' : 'keyword',
    matched_terms: primaryHits.concat(keywordHits),
    min_q: minQ,
    max_q: maxQ
  }));
});

let status = 'ok';
if (dbError) status = 'unavailable';
else if (!rows.length) status = 'empty';

return [{ json: { compatible: compatible, excluded: excluded, database_status: status, database_error: dbError ? String(dbError.error.message || dbError.error) : '', database_count: rows.length } }];

const d = $input.first().json;
const sub = $('Classification Fallback Handler').first().json;
const loc = String(sub.location || '').toLowerCase();
const qty = Number(sub.quantity_kg);

const scored = d.compatible.map(function (r) {
  const reasons = [];
  let materialScore;
  if (r.material_match === 'category') { materialScore = 50; reasons.push('Accepts ' + r.matched_terms.join(', ') + ' (direct material match)'); }
  else { materialScore = 35; reasons.push('Accepts related material: ' + r.matched_terms.join(', ')); }

  let qtyScore = 30;
  if (r.min_q > 0 && qty < r.min_q * 1.5) { qtyScore = 22; reasons.push('Quantity ' + qty + ' kg is just above its ' + r.min_q + ' kg minimum'); }
  else reasons.push('Quantity ' + qty + ' kg fits its ' + r.min_q + '-' + (r.max_q || 'any') + ' kg range');

  const city = String(r.city || '').toLowerCase().trim();
  const region = String(r.region || '').toLowerCase().trim();
  let proxScore = 4;
  let proximity = 'Different or unknown area';
  if (city && loc.indexOf(city) >= 0) { proxScore = 20; proximity = 'Same city (location text match)'; }
  else if (region && loc.indexOf(region) >= 0) { proxScore = 12; proximity = 'Same state/region (location text match)'; }
  reasons.push(proximity + ' - distance and transport cost not verified');

  return Object.assign({}, r, {
    score: materialScore + qtyScore + proxScore,
    score_breakdown: { material: materialScore, quantity: qtyScore, proximity: proxScore },
    proximity: proximity,
    explanation: reasons.join('; ') + '.'
  });
});

scored.sort(function (a, b) { return b.score - a.score; });
const top = scored.slice(0, 3).map(function (r, i) { return Object.assign({}, r, { rank: i + 1 }); });

return [{ json: Object.assign({}, d, { top_matches: top, total_compatible: scored.length }) }];

const m = $input.first().json;
const sub = $('Classification Fallback Handler').first().json;
const c = sub.classification;
function esc(x) { return String(x === undefined || x === null ? '' : x).split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;').split('"').join('&quot;'); }
function list(a) { return a && a.length ? '<ul>' + a.map(function (i) { return '<li>' + esc(i) + '</li>'; }).join('') + '</ul>' : '<p>None noted.</p>'; }

const notes = [];
if (sub.ai_failure_reason) notes.push('AI classification was unavailable (' + sub.ai_failure_reason + '), so a rule-based fallback was used.');
if (m.database_status === 'unavailable') notes.push('The recycler database could not be read: ' + m.database_error);
if (m.database_status === 'empty') notes.push('The recycler database is empty - add recycler records to get matches.');
notes.push('Distance and transport costs have NOT been verified: no geocoding or routing service is configured, so proximity is based on matching location text only.');
notes.push('Organisations marked SAMPLE are fictional demo records, not verified recyclers. Always confirm acceptance criteria, authorisation and terms directly.');
notes.push('No prices or guaranteed buyers are implied.');
sub.warnings.forEach(function (w) { notes.push(w); });

const oppHtml = c.value_opportunities.map(function (o) {
  return '<li><b>' + esc(o.product) + '</b> (' + esc(o.industry) + ') - ' + esc(o.explanation) + '</li>';
}).join('');

let matchHtml;
if (m.top_matches.length) {
  matchHtml = m.top_matches.map(function (r) {
    const sample = String(r.record_status || '').toUpperCase().indexOf('SAMPLE') >= 0;
    const contacts = [];
    if (r.contact_email) contacts.push('Email: ' + esc(r.contact_email));
    if (r.contact_phone) contacts.push('Phone: ' + esc(r.contact_phone));
    if (r.website) contacts.push('Website: ' + esc(r.website));
    return '<div style="border:1px solid #ccc;border-radius:6px;padding:10px;margin:8px 0">' +
      '<b>#' + r.rank + ' ' + esc(r.org_name) + '</b> - match score ' + r.score + '/100' +
      (sample ? ' <span style="background:#ffe08a;padding:2px 6px;border-radius:4px">SAMPLE / UNVERIFIED</span>' : '') +
      '<br>Location: ' + esc([r.city, r.region].filter(Boolean).join(', ')) +
      '<br>Reuse purpose: ' + esc(r.reuse_purpose) +
      '<br>Why matched: ' + esc(r.explanation) +
      '<br>Contact: ' + (contacts.length ? contacts.join(' | ') : 'Not available in database') +
      '</div>';
  }).join('');
} else {
  matchHtml = '<p><b>No compatible organisations found.</b> ' +
    (m.database_status === 'ok' ? 'None of the ' + m.database_count + ' records accept this material at this quantity. Try adjusting the quantity, adding more detail, or adding recyclers to the database.' : 'See notes below.') + '</p>';
}

const excludedHtml = m.excluded.length ? '<details><summary>' + m.excluded.length + ' organisation(s) excluded as incompatible</summary>' + list(m.excluded.map(function (e) { return e.org_name + ': ' + e.reason; })) + '</details>' : '';

const html = '<h1>WasteMatch AI results</h1>' +
  '<h2>1. Your submission</h2><p><b>Category:</b> ' + esc(sub.category_label) + ' | <b>Quantity:</b> ' + esc(sub.quantity_kg) + ' kg | <b>Location:</b> ' + esc(sub.location) + ' | <b>Condition:</b> ' + esc(sub.condition) + '</p>' +
  '<h2>2. Material understanding</h2><p><i>' + esc(c.source_label) + '</i></p>' +
  '<p><b>Material:</b> ' + esc(c.material_type) + ' - ' + esc(c.subtype) + ' (confidence: ' + esc(c.confidence) + ')</p>' +
  '<p><b>Condition assessment:</b> ' + esc(c.condition_assessment) + '</p>' +
  '<p><b>Recyclability considerations:</b> ' + esc(c.recyclability_notes) + '</p>' +
  '<p><b>Caveat:</b> ' + esc(c.certainty_caveat) + '</p>' +
  (c.contamination_risks.length ? '<p><b>Contamination risks:</b></p>' + list(c.contamination_risks) : '') +
  (c.handling_precautions.length ? '<p><b>Handling precautions:</b></p>' + list(c.handling_precautions) : '') +
  '<h2>3. Hidden value - potential reuse opportunities</h2><ul>' + oppHtml + '</ul>' +
  '<p><b>Industries that may reuse it:</b> ' + esc(c.reuse_industries.join(', ')) + '</p>' +
  '<h2>4. Top compatible matches</h2>' + matchHtml + excludedHtml +
  '<h2>5. Missing information</h2>' + list(c.missing_information) +
  '<h2>Important notes</h2>' + list(notes);

const results = {
  waste_category: sub.category,
  classification: c,
  reuse_opportunities: c.value_opportunities,
  top_matches: m.top_matches.map(function (r) {
    return { rank: r.rank, organization: r.org_name, score: r.score, score_breakdown: r.score_breakdown, explanation: r.explanation, city: r.city, region: r.region, reuse_purpose: r.reuse_purpose, record_status: r.record_status, contact_email: r.contact_email || null, contact_phone: r.contact_phone || null, website: r.website || null };
  }),
  excluded: m.excluded,
  missing_information: c.missing_information,
  notes: notes
};

return [{ json: {
  results_html: html,
  email_html: html,
  email: sub.email,
  send_email: !!sub.email,
  match_count: m.top_matches.length,
  results: results
} }];

